// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    SimpleSuicide c;
    function setUp() public { c = new SimpleSuicide(); }

    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != address(0));
        // fund the target so a successful selfdestruct is externally observable
        vm.deal(address(c), amount);

        vm.prank(caller);
        bool ok;
        try c.sudicideAnyone() { ok = true; } catch { ok = false; }

        // General rule: any successful call to sudicideAnyone must have been
        // made by the contract's owner (the deployer = this test contract).
        // The mutant lets arbitrary non-owners succeed, breaking this.
        assertTrue(!ok || caller == address(this));
    }
}
